// Search returns every direct child from BOTH intake folders. Prioritize
// recent uploads before the per-workspace Limit node so an old backlog or a
// repeatedly failing legacy file cannot prevent a new transcript/summary pair
// from being ingested.
const files = $input.all()
  .map(i => i.json)
  .filter(f => f && f.file_id);

if (files.length === 0) {
  return [{ json: { no_files: true } }];
}

const timestamp = (file) => {
  const parsed = Date.parse(file.created_time || '');
  return Number.isFinite(parsed) ? parsed : 0;
};

return files
  .sort((a, b) => timestamp(b) - timestamp(a))
  .map(f => ({ json: f, pairedItem: { item: 0 } }));

// Runs once per outer-loop iteration, BEFORE the download, so that a file that
// fails to download or parse can still be named in the failure log.
const meta = $input.first().json;
const cfg = meta;

if (meta.drive_search_error) {
  return [{ json: {
    ...meta,
    ingestion_type: meta.source_branch,
    error: `Drive search failed: ${meta.drive_search_error}`
  }, pairedItem: { item: 0 } }];
}

const base = String(meta.file_name || '').replace(/\.(txt|md)$/i, '').trim();
if (!base) {
  throw new Error('File has no usable name');
}

// Decide the type from the FILE, not from a hand-edited workflow field.
// This is what removes the manual transcripts/summaries switch: a mixed batch
// now ingests correctly in a single run.
const isSummary = /[\s\-_]*(summary|summaryplaud)\s*$/i.test(base);
const ingestionType = isSummary ? 'summaries' : 'transcripts';

// Strip exactly ONE trailing type suffix. Gemini exports are genuinely named
// "<name>_transcript_transcript.txt" -> id "<name>_transcript", which is what
// is already in Supabase. Stripping more than one would split those videos.
// "_SummaryPlaud" is included because it was not before -- that is why
// "PLANNING RAMBLE_SummaryPlaud" landed as its own row instead of merging.
const sourceVideoId = base
  .replace(/[\s\-_]*(transcript|summary|summaryplaud)\s*$/i, '')
  .trim();

// Collapse separator runs. Without the second replace "X_Y - SO WHAT" became
// "X Y   SO WHAT" (three spaces). HTML collapses that to one space on screen,
// so VP prints the name correctly and then cannot find it again -- the backend
// lookup was whitespace-exact. 269 of 275 stored titles hit this.
const title = sourceVideoId
  .replace(/[-_]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Destination follows the DETECTED type, not the folder the file came from, so
// a summary dropped in the transcripts intake still files itself correctly.
const doneFolderId =
  (isSummary ? cfg.summaries_done_folder_id : cfg.transcripts_done_folder_id)
  || meta.done_folder_id;

if (!doneFolderId) {
  throw new Error(
    `No completed folder configured for ${ingestionType} ` +
    `(configure the completed folder in public.clients_registry)`
  );
}

return [{
  json: {
    ...meta,
    client_id: cfg.client_id,
    client_slug: cfg.client_slug,
    ingestion_type: ingestionType,
    source_video_id: sourceVideoId,
    title,
    source_file: `${sourceVideoId}.mp4`,
    done_folder_id: doneFolderId,
    failed_folder_id: null,
  },
  pairedItem: { item: 0 },
}];

const meta = $('Resolve Ingestion Manifest').first().json;

const rawText = String($input.first().json.data || '').trim();
if (!rawText) {
  throw new Error(`Empty file: ${meta.file_name}`);
}

const item = {
  ...meta,
  raw_text: rawText,
  word_count_total: rawText.split(/\s+/).length,
};

// ---- summaries: one embedding for the whole document, no chunks ------------
if (item.ingestion_type === 'summaries') {
  return [{
    json: {
      ...item,
      has_timestamps: false,
      summary_text: item.raw_text,
      topics: [],
      is_auto_summary: false,
      chunks: [],
      embedding_inputs: [item.raw_text],
    },
    pairedItem: { item: 0 },
  }];
}

// ---- transcripts ----------------------------------------------------------
const TARGET_WORDS = 600;
const OVERLAP_WORDS = 100;
const MAX_CHUNKS = 500;
// One embeddings request carries every chunk. text-embedding-3-small caps a
// request at ~300k tokens; ~4 chars per token gives a safe ceiling of 900k
// chars. Failing loudly here beats a truncated vector set.
const MAX_EMBED_CHARS = 900000;

function timestampToSeconds(h, m, s) {
  if (s !== undefined && s !== null) {
    return parseInt(h, 10) * 3600 + parseInt(m, 10) * 60 + parseInt(s, 10);
  }
  return parseInt(h, 10) * 60 + parseInt(m, 10);
}

// Find all timestamp positions in the raw text
const matches = [];
const re = /\[(\d{1,2}):(\d{2})(?::(\d{2}))?\]/g;
let m;
while ((m = re.exec(rawText)) !== null) {
  matches.push({
    pos: m.index,
    seconds: timestampToSeconds(m[1], m[2], m[3]),
    fullMatch: m[0],
  });
}

const hasTimestamps = matches.length > 0;

function finish(chunks, timestamped) {
  if (chunks.length > MAX_CHUNKS) {
    throw new Error(`Too many chunks (${chunks.length}) for ${item.file_name}`);
  }
  const inputs = chunks.map(c => c.transcript_text);
  const totalChars = inputs.reduce((n, t) => n + t.length, 0);
  if (totalChars > MAX_EMBED_CHARS) {
    throw new Error(
      `${item.file_name} is too large for a single embeddings request ` +
      `(${totalChars} chars across ${chunks.length} chunks); split the file`
    );
  }
  return [{
    json: {
      ...item,
      has_timestamps: timestamped,
      summary_text: null,
      topics: [],
      is_auto_summary: false,
      chunks,
      embedding_inputs: inputs,
    },
    pairedItem: { item: 0 },
  }];
}

// No timestamps -- fall back to plain word chunking
if (!hasTimestamps) {
  const words = rawText.split(/\s+/).filter(Boolean);
  const chunks = [];
  let cursor = 0;
  let chunkIndex = 0;

  while (cursor < words.length) {
    const targetEnd = Math.min(cursor + TARGET_WORDS, words.length);
    const chunkWords = words.slice(cursor, targetEnd);
    if (chunkWords.length === 0) break;

    chunks.push({
      chunk_index: chunkIndex,
      start_seconds: 0,
      end_seconds: 0,
      speaker: null,
      transcript_text: chunkWords.join(' '),
      word_count: chunkWords.length,
    });

    chunkIndex++;
    if (targetEnd === words.length) break;
    const nextCursor = targetEnd - OVERLAP_WORDS;
    if (nextCursor <= cursor) break;
    cursor = nextCursor;
  }

  return finish(chunks, false);
}

// Build segments -- keep the timestamp marker WITH the text that follows
const segments = [];
for (let i = 0; i < matches.length; i++) {
  const startPos = matches[i].pos;
  const endPos = i + 1 < matches.length ? matches[i + 1].pos : rawText.length;
  const text = rawText.slice(startPos, endPos).trim();
  if (text.length === 0) continue;

  segments.push({
    start_seconds: matches[i].seconds,
    end_seconds: i + 1 < matches.length ? matches[i + 1].seconds : matches[i].seconds,
    text,
  });
}

// Group segments into chunks while guaranteeing that each pass advances.
const chunks = [];
let chunkIndex = 0;
let segIdx = 0;

function countWords(s) {
  return s.replace(/\[\d{1,2}:\d{2}(?::\d{2})?\]/g, '')
          .split(/\s+/)
          .filter(Boolean).length;
}

while (segIdx < segments.length) {
  const chunkStart = segIdx;
  const current = [];
  let currentWords = 0;
  let currentEnd = segments[segIdx].end_seconds;

  while (segIdx < segments.length) {
    const segmentWords = countWords(segments[segIdx].text);
    if (currentWords > 0 && currentWords + segmentWords > TARGET_WORDS) break;
    current.push(segments[segIdx].text);
    currentWords += segmentWords;
    currentEnd = segments[segIdx].end_seconds;
    segIdx++;
  }

  chunks.push({
    chunk_index: chunkIndex++,
    start_seconds: segments[chunkStart].start_seconds,
    end_seconds: currentEnd,
    speaker: null,
    transcript_text: current.join(' ').replace(/\s+/g, ' ').trim(),
    word_count: currentWords,
  });

  if (segIdx >= segments.length) break;

  let overlapStart = segIdx;
  let overlapWords = 0;
  while (overlapStart > chunkStart && overlapWords < OVERLAP_WORDS) {
    overlapStart--;
    overlapWords += countWords(segments[overlapStart].text);
  }
  // A single oversized timestamp segment cannot be overlapped safely. Move
  // to the next segment instead of processing the same segment forever.
  segIdx = overlapStart > chunkStart ? overlapStart : Math.max(segIdx, chunkStart + 1);
}

return finish(chunks, true);

const apiResponse = $input.first().json;
const parent = $('Prepare Content').first().json;

const embeddings = apiResponse?.data;
if (!Array.isArray(embeddings) || embeddings.length === 0) {
  throw new Error('Missing embeddings in OpenAI response');
}

const fmt = (arr) => (arr ? `[${arr.join(',')}]` : null);

let summary_embedding = null;
let chunkEmbeddings = embeddings;

if (parent.ingestion_type === 'summaries') {
  summary_embedding = fmt(embeddings[0].embedding);
  chunkEmbeddings = [];
}

let chunks_with_embeddings = [];
if (parent.chunks && parent.chunks.length > 0) {
  if (chunkEmbeddings.length !== parent.chunks.length) {
    throw new Error(
      `Chunk embedding mismatch for ${parent.file_name}: ` +
      `got ${chunkEmbeddings.length}, expected ${parent.chunks.length}`
    );
  }
  chunks_with_embeddings = parent.chunks.map((c, i) => ({
    ...c,
    embedding: fmt(chunkEmbeddings[i].embedding),
  }));
}

return [{
  json: {
    client_id: parent.client_id,
    source_video_id: parent.source_video_id,
    title: parent.title,
    source_file: parent.source_file,
    has_timestamps: parent.has_timestamps,
    b2_bucket: parent.b2_bucket || null,
    b2_path: parent.b2_path || null,
    thumbnail_b2_path: parent.thumbnail_b2_path || null,
    // No zero-width-space prefix. The old node prepended \u200B to every
    // summary, which broke every exact-text lookup against summary_text.
    summary_text: parent.summary_text || null,
    summary_embedding,
    topics: parent.topics && parent.topics.length > 0 ? parent.topics : null,
    is_auto_summary: parent.is_auto_summary,
    chunks: chunks_with_embeddings,
    chunk_count: chunks_with_embeddings.length,
    file_id: parent.file_id,
    file_name: parent.file_name,
    ingestion_type: parent.ingestion_type,
    done_folder_id: parent.done_folder_id,
  },
  pairedItem: { item: 0 },
}];
